package paasio

import (
	"io"
	"sync"
)

// readCounter wraps an io.Reader and counts the total number of bytes
// read and the total number of Read operations.
type readCounter struct {
	reader io.Reader
	n      int64
	nops   int
	mu     sync.Mutex
}

// writeCounter wraps an io.Writer and counts the total number of bytes
// written and the total number of Write operations.
type writeCounter struct {
	writer io.Writer
	n      int64
	nops   int
	mu     sync.Mutex
}

// readWriteCounter combines a readCounter and a writeCounter so that it
// satisfies the ReadWriteCounter interface.
type readWriteCounter struct {
	*readCounter
	*writeCounter
}

func NewWriteCounter(writer io.Writer) WriteCounter {
	return &writeCounter{writer: writer}
}

func NewReadCounter(reader io.Reader) ReadCounter {
	return &readCounter{reader: reader}
}

func NewReadWriteCounter(readwriter io.ReadWriter) ReadWriteCounter {
	return &readWriteCounter{
		readCounter:  &readCounter{reader: readwriter},
		writeCounter: &writeCounter{writer: readwriter},
	}
}

func (rc *readCounter) Read(p []byte) (int, error) {
	n, err := rc.reader.Read(p)
	rc.mu.Lock()
	rc.n += int64(n)
	rc.nops++
	rc.mu.Unlock()
	return n, err
}

func (rc *readCounter) ReadCount() (int64, int) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	return rc.n, rc.nops
}

func (wc *writeCounter) Write(p []byte) (int, error) {
	n, err := wc.writer.Write(p)
	wc.mu.Lock()
	wc.n += int64(n)
	wc.nops++
	wc.mu.Unlock()
	return n, err
}

func (wc *writeCounter) WriteCount() (int64, int) {
	wc.mu.Lock()
	defer wc.mu.Unlock()
	return wc.n, wc.nops
}
